//! Exact ATC catalog available to 1601EQ January 2018 (ENCS).
//!
//! Grounding:
//! - Offline eBIRForms 7.9.6 `xml/atcCodes.xml`, 153,753 bytes,
//!   SHA-256 `16e4db6ce456a6fb0a97f085cf8ef19349c2f6fc183971e97d4e253f63cdd22b`;
//! - `loadXMLATC('xml/atcCodes.xml')` line 1522, `loadATC` lines 1638-1680,
//!   `getWithholdingAgentATC` lines 2643-2662, `changeATCRate` lines
//!   2665-2692.
//!
//! The whole chain lives in the HTA, so this catalog does not depend on the
//! seven scripts 1601EQ fails to load. Rendering the rows does
//! (`formatCurrency` is in the absent `bir-formatter.js`), so this module
//! pins the lookup domain only.
//!
//! `loadATC` keeps a record when the raw text contains the substring
//! `1601EQ` and reads only fields 0-3 as code, description, rate and
//! category; it hardcodes base, compType, constTaxDue, minimum and maximum
//! to the empty string, so those XML columns are never consulted.
//!
//! `getWithholdingAgentATC` then narrows by `category == "P"` or `"G"`, so
//! the lookup key is the pair, not the code alone: 96 codes appear once in
//! each category.
//!
//! Four records tagged `1601EQ` are malformed in the source and carry only
//! nine fields: their rate is written into the description after a
//! semicolon instead of occupying its own `~` column. `loadATC` therefore
//! reads their category as the rate and leaves the category empty, and
//! `getWithholdingAgentATC` drops them from both dropdowns. They are
//! recorded in `unreachable_records` rather than silently omitted.

const std = @import("std");
const validation = @import("validation.zig");

pub const source_byte_length: usize = 153_753;
pub const source_sha256 =
    "16e4db6ce456a6fb0a97f085cf8ef19349c2f6fc183971e97d4e253f63cdd22b";

/// `atcCount` declared by the file header.
pub const declared_atc_count: usize = 1085;
/// Records passing `loadATC`'s `indexOf('1601EQ')` test.
pub const matched_record_count: usize = 211;

pub const Category = enum {
    private,
    government,

    /// `getWithholdingAgentATC` compares against the `optCategory` value.
    pub fn token(self: Category) []const u8 {
        return switch (self) {
            .private => "P",
            .government => "G",
        };
    }

    pub fn fromIdentity(category: validation.Category) ?Category {
        return switch (category) {
            .private => .private,
            .government => .government,
            .none => null,
        };
    }
};

pub const AtcRecord = struct {
    code: []const u8,
    description: []const u8,
    /// Verbatim from the source column. Not parsed here: the HTA passes the
    /// string through `changeATCRate` and into the DOM without arithmetic.
    rate: []const u8,
    category: Category,
};

/// Malformed source record that `getWithholdingAgentATC` can never surface.
pub const UnreachableRecord = struct {
    code: []const u8,
    /// Carries the rate inline, which is why the column layout shifts.
    description: []const u8,
};

