pub const unreachable_records = [_]UnreachableRecord{
    .{ .code = "WI240", .description = "Distributive share of individual partners in a taxable partnership, association, joint account or joint venture or consortium;20" },
    .{ .code = "WI341", .description = "Royalties paid to NRAETB on cinematographic fils and similar works;20" },
    .{ .code = "WC212", .description = "Cash dividend payment by domestic corporation to citizens and resident aliens/NRFCs; 25" },
    .{ .code = "WC213", .description = "Property dividend payment by domestic corporation to citizens and resident aliens/NRFCs;25" },
};

pub const private_record_count: usize = 111;
pub const government_record_count: usize = 96;

pub fn countFor(category: Category) usize {
    var total: usize = 0;
    for (records) |record| {
        if (record.category == category) total += 1;
    }
    return total;
}

/// `getWithholdingAgentATC` narrows by category before matching a code, so
/// the same code can resolve to different rates in each category.
pub fn find(category: Category, code: []const u8) ?*const AtcRecord {
    for (&records) |*record| {
        if (record.category == category and std.mem.eql(u8, record.code, code)) {
            return record;
        }
    }
    return null;
}

pub fn isUnreachable(code: []const u8) bool {
    for (unreachable_records) |record| {
        if (std.mem.eql(u8, record.code, code)) return true;
    }
    return false;
}

/// Codes `changeATCRate` overrides for return periods at or before 2018.
const superseded_rates = [_]struct { code: []const u8, rate: []const u8 }{
    .{ .code = "WI650", .rate = "25.0" },
    .{ .code = "WC650", .rate = "25.0" },
    .{ .code = "WI651", .rate = "32.0" },
    .{ .code = "WC651", .rate = "32.0" },
    .{ .code = "WI663", .rate = "20.0" },
    .{ .code = "WC663", .rate = "20.0" },
    .{ .code = "WI710", .rate = "20.0" },
    .{ .code = "WC710", .rate = "20.0" },
};

/// `changeATCRate` lines 2665-2692, applied by `getWithholdingAgentATC` as
/// each row is built, so the rate tracks whatever Item 1 currently holds.
///
/// HTA compares the raw Item 1 string with `returnPeriod <= 2018`, which
/// coerces numerically. An empty year coerces to zero and therefore takes
/// the superseded branch, so a blank Item 1 yields the pre-2019 rates.
pub fn effectiveRate(
    code: []const u8,
    source_rate: []const u8,
    return_year: validation.Year,
) []const u8 {
    const year: i32 = switch (return_year) {
        .empty => 0,
        .value => |value| value,
    };
    if (year > 2018) return source_rate;
    for (superseded_rates) |entry| {
        if (std.mem.eql(u8, entry.code, code)) return entry.rate;
    }
    return source_rate;
}

test "1601EQ ATC catalog matches the source record accounting" {
    try std.testing.expectEqual(matched_record_count, records.len + unreachable_records.len);
    try std.testing.expectEqual(@as(usize, 211), matched_record_count);
    try std.testing.expectEqual(@as(usize, 207), records.len);
    try std.testing.expectEqual(@as(usize, 4), unreachable_records.len);
}

test "1601EQ ATC codes are unique inside a category and shared across them" {
    try std.testing.expectEqual(private_record_count, countFor(.private));
    try std.testing.expectEqual(government_record_count, countFor(.government));
    try std.testing.expectEqual(records.len, countFor(.private) + countFor(.government));

    for (records, 0..) |record, index| {
        try std.testing.expect(record.code.len > 0);
        try std.testing.expect(record.rate.len > 0);
        for (records[index + 1 ..]) |other| {
            if (record.category != other.category) continue;
            try std.testing.expect(!std.mem.eql(u8, record.code, other.code));
        }
    }

    // A code carried by both categories resolves independently in each.
    try std.testing.expect(find(.private, "WI010") != null);
    try std.testing.expect(find(.government, "WI010") != null);
}

test "1601EQ malformed source records reach neither dropdown" {
    try std.testing.expect(isUnreachable("WI240"));
    try std.testing.expect(isUnreachable("WI341"));
    try std.testing.expect(isUnreachable("WC212"));
    try std.testing.expect(isUnreachable("WC213"));

    for (unreachable_records) |missing| {
        try std.testing.expect(find(.private, missing.code) == null);
        try std.testing.expect(find(.government, missing.code) == null);
        // The rate is stranded in the description, which is the defect.
        try std.testing.expect(std.mem.indexOfScalar(u8, missing.description, ';') != null);
    }
}

test "1601EQ category token matches the optCategory values" {
    try std.testing.expectEqualStrings("P", Category.private.token());
    try std.testing.expectEqualStrings("G", Category.government.token());
    try std.testing.expectEqual(Category.private, Category.fromIdentity(.private).?);
    try std.testing.expectEqual(Category.government, Category.fromIdentity(.government).?);
    try std.testing.expect(Category.fromIdentity(.none) == null);
}

test "1601EQ superseded ATC rates apply only at or before the 2018 return period" {
    const y2018: validation.Year = .{ .value = 2018 };
    const y2019: validation.Year = .{ .value = 2019 };

    try std.testing.expectEqualStrings("25.0", effectiveRate("WI650", "15.0", y2018));
    try std.testing.expectEqualStrings("32.0", effectiveRate("WC651", "15.0", y2018));
    try std.testing.expectEqualStrings("20.0", effectiveRate("WI710", "15.0", y2018));
    try std.testing.expectEqualStrings("15.0", effectiveRate("WI650", "15.0", y2019));
    try std.testing.expectEqualStrings("15.0", effectiveRate("WC651", "15.0", y2019));

    // Codes outside the override list keep the source rate either way.
    try std.testing.expectEqualStrings("5.0", effectiveRate("WI010", "5.0", y2018));
    try std.testing.expectEqualStrings("5.0", effectiveRate("WI010", "5.0", y2019));
}

test "1601EQ blank Item 1 coerces to zero and takes the superseded rates" {
    try std.testing.expectEqualStrings("25.0", effectiveRate("WI650", "15.0", .empty));
    try std.testing.expectEqualStrings("15.0", effectiveRate("WI010", "15.0", .empty));
}

test "1601EQ every catalog rate survives a round trip through the rate rule" {
    const y2019: validation.Year = .{ .value = 2019 };
    for (records) |record| {
        try std.testing.expectEqualStrings(
            record.rate,
            effectiveRate(record.code, record.rate, y2019),
        );
    }
}
